create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','manager','accountant','staff','tenant');
create type public.room_status as enum ('available','occupied','maintenance','reserved');
create type public.invoice_status as enum ('draft','issued','partial','paid','overdue','void');
create type public.payment_method as enum ('cash','bank_transfer','promptpay','card','other');

create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null check(length(trim(name)) between 1 and 120), owner_user_id uuid not null references auth.users(id) on delete restrict, currency text not null default 'THB' check(currency='THB'), timezone text not null default 'Asia/Bangkok', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organization_members (organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.member_role not null default 'staff', created_at timestamptz not null default now(), primary key(organization_id,user_id));
create table public.properties (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, address text, province text, postal_code text, phone text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,organization_id));
create table public.rooms (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, property_id uuid not null, room_number text not null, floor integer not null default 1 check(floor>=0), monthly_rent numeric(12,2) not null check(monthly_rent>=0), status public.room_status not null default 'available', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(property_id,organization_id) references public.properties(id,organization_id) on delete cascade, unique(property_id,room_number), unique(id,organization_id));
create table public.tenants (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, auth_user_id uuid references auth.users(id) on delete set null, full_name text not null, email text, phone text, identity_number text, emergency_contact text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,organization_id));
create table public.leases (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, room_id uuid not null, tenant_id uuid not null, start_date date not null, end_date date, rent_amount numeric(12,2) not null check(rent_amount>=0), deposit_amount numeric(12,2) not null default 0 check(deposit_amount>=0), billing_day smallint not null default 1 check(billing_day between 1 and 28), status text not null default 'active' check(status in ('active','ended','draft')), terms jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(room_id,organization_id) references public.rooms(id,organization_id), foreign key(tenant_id,organization_id) references public.tenants(id,organization_id), check(end_date is null or end_date>=start_date), unique(id,organization_id));
create unique index leases_one_active_per_room on public.leases(room_id) where status='active';
create table public.utility_rates (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, property_id uuid not null, utility text not null check(utility in ('water','electricity')), unit_rate numeric(12,4) not null check(unit_rate>=0), effective_from date not null, effective_to date, fixed_fee numeric(12,2) not null default 0 check(fixed_fee>=0), source_reference text not null, created_at timestamptz not null default now(), foreign key(property_id,organization_id) references public.properties(id,organization_id), check(effective_to is null or effective_to>=effective_from), unique(property_id,utility,effective_from));
create table public.meter_readings (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, room_id uuid not null, utility text not null check(utility in ('water','electricity')), reading_value numeric(14,3) not null check(reading_value>=0), read_at date not null, evidence_path text, captured_by uuid references auth.users(id), notes text, created_at timestamptz not null default now(), foreign key(room_id,organization_id) references public.rooms(id,organization_id), unique(room_id,utility,read_at));
create table public.invoices (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, tenant_id uuid not null, lease_id uuid not null, invoice_number text not null, period_start date not null, period_end date not null, issue_date date not null default ((now() at time zone 'Asia/Bangkok')::date), due_date date not null, subtotal numeric(12,2) not null default 0 check(subtotal>=0), total numeric(12,2) not null default 0 check(total>=0), status public.invoice_status not null default 'draft', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(tenant_id,organization_id) references public.tenants(id,organization_id), foreign key(lease_id,organization_id) references public.leases(id,organization_id), unique(organization_id,invoice_number), unique(lease_id,period_start,period_end));
create table public.invoice_items (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, invoice_id uuid not null references public.invoices(id) on delete cascade, description text not null, quantity numeric(12,3) not null default 1 check(quantity>0), unit_price numeric(12,2) not null check(unit_price>=0), amount numeric(12,2) not null check(amount>=0), metadata jsonb not null default '{}');
create table public.payments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, invoice_id uuid not null references public.invoices(id), amount numeric(12,2) not null check(amount>0), method public.payment_method not null, received_at timestamptz not null default now(), reference text, evidence_path text, received_by uuid references auth.users(id), notes text, created_at timestamptz not null default now());
create table public.expenses (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, property_id uuid, category text not null, description text not null, amount numeric(12,2) not null check(amount>0), incurred_on date not null, vendor text, receipt_path text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), foreign key(property_id,organization_id) references public.properties(id,organization_id));
create table public.security_deposits (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, lease_id uuid not null, amount_received numeric(12,2) not null default 0 check(amount_received>=0), amount_refunded numeric(12,2) not null default 0 check(amount_refunded>=0), amount_deducted numeric(12,2) not null default 0 check(amount_deducted>=0), status text not null default 'held' check(status in ('held','partially_refunded','refunded','forfeited')), settlement_due_on date, settled_on date, notes text, created_at timestamptz not null default now(), foreign key(lease_id,organization_id) references public.leases(id,organization_id), check(amount_refunded+amount_deducted<=amount_received));
create table public.maintenance_tickets (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, room_id uuid, tenant_id uuid, title text not null, description text, priority text not null default 'normal' check(priority in ('low','normal','high','urgent')), status text not null default 'open' check(status in ('open','in_progress','waiting','resolved','closed')), assigned_to uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), resolved_at timestamptz, foreign key(room_id,organization_id) references public.rooms(id,organization_id), foreign key(tenant_id,organization_id) references public.tenants(id,organization_id));
create table public.assets (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, property_id uuid not null, name text not null, serial_number text, purchased_on date, purchase_cost numeric(12,2) check(purchase_cost is null or purchase_cost>=0), next_service_on date, notes text, foreign key(property_id,organization_id) references public.properties(id,organization_id));
create table public.announcements (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, property_id uuid, title text not null, body text not null, publish_at timestamptz not null default now(), expires_at timestamptz, created_by uuid references auth.users(id), created_at timestamptz not null default now(), foreign key(property_id,organization_id) references public.properties(id,organization_id));
create table public.parcels (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, tenant_id uuid not null, carrier text, tracking_number text, received_at timestamptz not null default now(), collected_at timestamptz, collected_by text, notes text, foreign key(tenant_id,organization_id) references public.tenants(id,organization_id));
create table public.tasks (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, title text not null, details text, due_at timestamptz, status text not null default 'open' check(status in ('open','done','cancelled')), assigned_to uuid references auth.users(id), created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.audit_events (id bigint generated always as identity primary key, organization_id uuid not null references public.organizations(id) on delete cascade, actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id text, before_data jsonb, after_data jsonb, created_at timestamptz not null default now());

create or replace function public.is_org_member(target_org uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.organization_members m where m.organization_id=target_org and m.user_id=(select auth.uid())) $$;
revoke all on function public.is_org_member(uuid) from public;
grant execute on function public.is_org_member(uuid) to authenticated;
create or replace function public.is_staff_member(target_org uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.organization_members m where m.organization_id=target_org and m.user_id=(select auth.uid()) and m.role <> 'tenant') $$;
revoke all on function public.is_staff_member(uuid) from public;
grant execute on function public.is_staff_member(uuid) to authenticated;
create or replace function public.has_org_role(target_org uuid, allowed_roles public.member_role[]) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.organization_members m where m.organization_id=target_org and m.user_id=(select auth.uid()) and m.role = any(allowed_roles)) $$;
revoke all on function public.has_org_role(uuid,public.member_role[]) from public;
grant execute on function public.has_org_role(uuid,public.member_role[]) to authenticated;
create or replace function public.audit_row_change() returns trigger language plpgsql security definer set search_path=public,auth as $$ declare org uuid; row_id text; begin org:=coalesce((to_jsonb(new)->>'organization_id')::uuid,(to_jsonb(old)->>'organization_id')::uuid); row_id:=coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id'); insert into public.audit_events(organization_id,actor_id,action,entity_type,entity_id,before_data,after_data) values(org,auth.uid(),tg_op,tg_table_name,row_id,case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end); return coalesce(new,old); end $$;

do $$ declare t text; begin foreach t in array array['properties','rooms','tenants','leases','utility_rates','meter_readings','invoices','invoice_items','payments','expenses','security_deposits','maintenance_tickets','assets','announcements','parcels','tasks','audit_events'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy %I on public.%I for all to authenticated using (public.is_staff_member(organization_id)) with check (public.is_staff_member(organization_id))',t||'_org_access',t); end loop; end $$;
drop policy audit_events_org_access on public.audit_events;
create policy audit_events_member_read on public.audit_events for select to authenticated using(public.is_staff_member(organization_id));
drop policy invoices_org_access on public.invoices;
create policy invoices_staff_read on public.invoices for select to authenticated using(public.is_staff_member(organization_id));
create policy invoices_finance_manage on public.invoices for all to authenticated using(public.has_org_role(organization_id,array['owner','manager','accountant']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','manager','accountant']::public.member_role[]));
drop policy invoice_items_org_access on public.invoice_items;
create policy invoice_items_staff_read on public.invoice_items for select to authenticated using(public.is_staff_member(organization_id));
create policy invoice_items_finance_manage on public.invoice_items for all to authenticated using(public.has_org_role(organization_id,array['owner','manager','accountant']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','manager','accountant']::public.member_role[]));
drop policy payments_org_access on public.payments;
create policy payments_staff_read on public.payments for select to authenticated using(public.is_staff_member(organization_id));
create policy payments_finance_manage on public.payments for all to authenticated using(public.has_org_role(organization_id,array['owner','manager','accountant']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','manager','accountant']::public.member_role[]));
drop policy expenses_org_access on public.expenses;
create policy expenses_staff_read on public.expenses for select to authenticated using(public.is_staff_member(organization_id));
create policy expenses_finance_manage on public.expenses for all to authenticated using(public.has_org_role(organization_id,array['owner','manager','accountant']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','manager','accountant']::public.member_role[]));
drop policy security_deposits_org_access on public.security_deposits;
create policy deposits_staff_read on public.security_deposits for select to authenticated using(public.is_staff_member(organization_id));
create policy deposits_finance_manage on public.security_deposits for all to authenticated using(public.has_org_role(organization_id,array['owner','manager','accountant']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','manager','accountant']::public.member_role[]));
alter table public.organizations enable row level security;
create policy organizations_member_read on public.organizations for select to authenticated using(public.is_org_member(id));
create policy organizations_owner_insert on public.organizations for insert to authenticated with check(owner_user_id=(select auth.uid()));
create policy organizations_owner_update on public.organizations for update to authenticated using(owner_user_id=(select auth.uid())) with check(owner_user_id=(select auth.uid()));
alter table public.organization_members enable row level security;
create policy members_read_same_org on public.organization_members for select to authenticated using(public.is_staff_member(organization_id));
create policy owner_manage_members on public.organization_members for all to authenticated using(exists(select 1 from public.organizations o where o.id=organization_id and o.owner_user_id=(select auth.uid()))) with check(exists(select 1 from public.organizations o where o.id=organization_id and o.owner_user_id=(select auth.uid())));

create index rooms_org_status_idx on public.rooms(organization_id,status);
create index tenants_org_name_idx on public.tenants(organization_id,full_name);
create index leases_org_status_idx on public.leases(organization_id,status);
create index readings_room_date_idx on public.meter_readings(room_id,utility,read_at desc);
create index invoices_org_due_idx on public.invoices(organization_id,due_date,status);
create index payments_invoice_received_idx on public.payments(invoice_id,received_at desc);
create index expenses_org_date_idx on public.expenses(organization_id,incurred_on desc);
create index tickets_org_status_idx on public.maintenance_tickets(organization_id,status,priority);
create index audits_org_created_idx on public.audit_events(organization_id,created_at desc);
do $$ declare t text; begin foreach t in array array['rooms','tenants','leases','invoices','payments','expenses','maintenance_tickets'] loop execute format('create trigger %I_audit after insert or update or delete on public.%I for each row execute function public.audit_row_change()',t,t); end loop; end $$;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('property-evidence','property-evidence',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do nothing;
create policy "Organization members read private evidence" on storage.objects for select to authenticated using(bucket_id='property-evidence' and public.is_staff_member((storage.foldername(name))[1]::uuid));
create policy "Organization members upload private evidence" on storage.objects for insert to authenticated with check(bucket_id='property-evidence' and public.is_staff_member((storage.foldername(name))[1]::uuid));
create policy "Organization members delete private evidence" on storage.objects for delete to authenticated using(bucket_id='property-evidence' and public.is_staff_member((storage.foldername(name))[1]::uuid));
